factorial.code:
import gleam/int
import gleam/io

pub fn factorial(n: Int) -> Int {
  case n {
    0 -> 1
    _ -> n * factorial(n - 1)
  }
}

pub fn main() -> Nil {
  factorial(10)
  |> int.to_string
  |> io.println
}

fizzbuzz.code:
import gleam/int
import gleam/io

fn fizzbuzz(n: Int) -> String {
  // case can match several subjects at once
  case n % 3, n % 5 {
    0, 0 -> "FizzBuzz"
    0, _ -> "Fizz"
    _, 0 -> "Buzz"
    _, _ -> int.to_string(n)
  }
}

pub fn main() -> Nil {
  // No loops: int.range folds over 1 to 15 (the upper bound is exclusive)
  int.range(from: 1, to: 16, with: Nil, run: fn(_, n) {
    io.println(fizzbuzz(n))
  })
}

