import gleam/int
import gleam/io

// A custom type with two variants; each variant is a record constructor.
pub type Shape {
  Rectangle(width: Int, height: Int)
  Triangle(base: Int, height: Int)
}

pub fn area(shape: Shape) -> Int {
  case shape {
    Rectangle(width:, height:) -> width * height
    Triangle(base:, height:) -> base * height / 2
  }
}

pub fn main() -> Nil {
  let rectangle = Rectangle(width: 3, height: 4)
  let triangle = Triangle(base: 10, height: 3)
  io.println("Rectangle: " <> int.to_string(area(rectangle)))
  io.println("Triangle: " <> int.to_string(area(triangle)))
}

