import gleam/int
import gleam/io
import gleam/list
import gleam/result

pub type MathError {
  NotANumber(String)
  DivisionByZero
}

fn parse(text: String) -> Result(Int, MathError) {
  int.parse(text) |> result.replace_error(NotANumber(text))
}

// Each `use` hands the rest of the block to result.try: an Error returns early.
fn divide(a: String, b: String) -> Result(Int, MathError) {
  use x <- result.try(parse(a))
  use y <- result.try(parse(b))
  case y {
    0 -> Error(DivisionByZero)
    _ -> Ok(x / y)
  }
}

pub fn main() -> Nil {
  use #(a, b) <- list.each([#("84", "2"), #("84", "two"), #("84", "0")])
  // case must be exhaustive: drop a branch and the program does not compile.
  io.println(case divide(a, b) {
    Ok(n) -> a <> " / " <> b <> " = " <> int.to_string(n)
    Error(NotANumber(text)) -> "not a number: " <> text
    Error(DivisionByZero) -> "cannot divide " <> a <> " by zero"
  })
}
